"""Complete hereditary/paraneoplastic chapter with twelve mechanism-based presentations."""
from create_oncology_cancer_genetics import rows,q,ref
from qbank_authoring import finalize
PN=ref('International consensus criteria for paraneoplastic neurological syndromes','https://pmc.ncbi.nlm.nih.gov/articles/PMC8237398/')
SL=ref('NCI small-cell lung cancer professional summary','https://www.cancer.gov/types/lung/hp/small-cell-lung-treatment-pdq')

q('A patient with small-cell lung cancer has hypotonic hyponatremia, clinically normal extracellular volume, inappropriately concentrated urine and no adrenal, thyroid or renal explanation. Which mechanism is most likely?', 'Inappropriate antidiuretic activity causing impaired free-water excretion',[
 ('Primary mineralocorticoid failure established by the lung histology','That requires a different endocrine assessment and usually has a different volume/potassium context.'),('Hyperglycemia-induced translocational hyponatremia','The stem specifies hypotonicity and excludes that explanation.'),('Maximally suppressed antidiuretic activity from primary polydipsia alone','That usually produces appropriately dilute urine.')],
 'The biochemical pattern matters more than the cancer association alone','**SCLC can produce SIADH physiology.**',['Exclude drugs, cortisol deficiency and other causes before attribution.','Urine osmolality and sodium are interpreted with volume status and clinical context.'],'**Treat according to symptoms, chronicity and correction risk.**',['Severe neurological symptoms require urgent protocol-based hypertonic saline.','Avoid overly rapid correction and address the cancer and reversible triggers.'],[['Serum','Hypotonic hyponatremia'],['Urine','Inappropriately concentrated'],['Mechanism','Impaired water excretion']],[SL],style='clinical_scenario')

q('A patient with SCLC develops profound hypokalemia, metabolic alkalosis, hyperglycemia and marked cortisol excess with high ACTH, but few classic cushingoid features. Which explanation is most likely?', 'Rapid-onset ectopic ACTH syndrome',[
 ('Primary adrenal insufficiency','That produces cortisol deficiency rather than marked excess.'),('Isolated SIADH','SIADH does not explain this cortisol and potassium pattern.'),('An aldosterone-producing adenoma as the sole explanation for high ACTH and cortisol','It does not account for the ACTH-dependent hypercortisolism.')],
 'Severe biochemical disease can precede the classic appearance','**Ectopic ACTH can cause rapidly progressive hypercortisolism.**',['High cortisol can activate mineralocorticoid pathways and worsen potassium loss.','Infection, thrombosis and metabolic complications can be prominent.'],'**Arrange urgent endocrine and oncology management.**',['Correct potassium and treat complications.','Control cortisol while addressing the tumor where feasible.'],[['ACTH/cortisol','Both high'],['Metabolic pattern','Hypokalemic alkalosis/hyperglycemia'],['Appearance','Classic stigmata may be limited']],[SL],style='clinical_scenario')

q('An older smoker has proximal leg weakness, dry mouth, reduced reflexes and an increment in compound muscle action potential after exercise. Which association is most likely?', 'Lambert–Eaton myasthenic syndrome associated with small-cell lung cancer',[
 ('Postsynaptic myasthenia gravis as the best fit for the entire pattern','Autonomic symptoms, depressed reflexes and facilitation favor a presynaptic syndrome.'),('Pure sensory neuronopathy','That would not explain the neuromuscular transmission pattern.'),('Steroid myopathy with an identical electrophysiological increment','Steroid myopathy does not produce the characteristic transmission findings.')],
 'Autonomic symptoms and facilitation point presynaptically','**LEMS commonly involves antibodies to presynaptic voltage-gated calcium channels.**',['Reduced acetylcholine release causes weakness.','Not every case is cancer-associated, but this context warrants a focused tumor search.'],'**Confirm the neurological diagnosis and assess for SCLC.**',['Treat the malignancy and provide syndrome-specific symptomatic care.','Continue appropriate surveillance when the initial tumor search is negative but risk remains high.'],[['Site','Presynaptic'],['Clues','Dry mouth/reduced reflexes'],['Electrophysiology','Increment/facilitation']],[PN],style='clinical_scenario')

q('A patient develops a subacute, painful, asymmetric sensory neuronopathy with anti-Hu antibodies. Which occult malignancy is a major concern?', 'Small-cell lung cancer',[
 ('Papillary thyroid microcarcinoma as the characteristic association','That is not the principal anti-Hu association.'),('Localized basal-cell skin carcinoma as the expected cause','This is not the typical high-risk association.'),('A benign colonic adenoma as sufficient proof of the syndrome’s source','The high-risk neurological pattern warrants a more appropriate cancer search.')],
 'The antibody helps direct but does not replace clinical evaluation','**Anti-Hu is a high-risk onconeural antibody strongly associated with SCLC.**',['Sensory neuronopathy is a recognized high-risk phenotype.','Toxic, nutritional, infectious and other neurological causes still need consideration.'],'**Coordinate neurological assessment and an appropriate malignancy search.**',['A negative first scan may not end surveillance in a high-risk case.','Treating the tumor may not reverse established neuronal loss.'],[['Phenotype','Sensory neuronopathy'],['Antibody','Anti-Hu'],['Tumor concern','SCLC']],[PN],style='clinical_scenario')

q('A woman develops a rapidly progressive cerebellar syndrome and confirmed anti-Yo antibodies. Which cancer group deserves particular attention?', 'Breast and gynecological malignancies',[
 ('Only colorectal adenomas','This is not the characteristic anti-Yo association.'),('Only thyroid adenomas','This does not match the recognized cancer association.'),('Only prostate cancer','This is neither anatomically applicable nor the relevant antibody association.')],
 'A subacute cerebellar syndrome may precede detection of the tumor','**Anti-Yo is associated with paraneoplastic cerebellar degeneration, particularly with breast and gynecological cancers.**',['Exclude structural, vascular, toxic and nutritional causes.','Antibody results require clinical correlation and reliable confirmation.'],'**Arrange targeted oncological evaluation alongside neurological care.**',['Early recognition can identify an occult malignancy.','Neurological recovery can be limited despite cancer control.'],[['Syndrome','Rapid cerebellar dysfunction'],['Antibody','Anti-Yo'],['Search','Breast/gynecological sites']],[PN],style='clinical_scenario')

q('A patient with metastatic adenocarcinoma has recurrent embolic strokes and valve vegetations. Repeated blood cultures remain negative, but infective causes have not yet been fully excluded. Which diagnosis is an important consideration?', 'Nonbacterial thrombotic endocarditis',[
 ('Atrial myxoma established solely by any valve lesion','The location and clinical context do not establish myxoma.'),('Nonbacterial disease proven by one negative culture','Culture-negative infective endocarditis must still be evaluated.'),('A harmless incidental finding because the tumor explains all strokes','Recurrent embolization requires active assessment and management.')],
 'Cancer-associated hypercoagulability can involve the valves','**NBTE involves sterile platelet–fibrin vegetations and can cause systemic emboli.**',['Malignancy and autoimmune conditions are important contexts.','Infective endocarditis remains a critical differential.'],'**Use echocardiographic, microbiological and clinical evaluation together.**',['Anticoagulation and tumor treatment are considered after bleeding and competing risks are assessed.','Do not label a vegetation sterile from culture negativity alone.'],[['Context','Cancer/hypercoagulability'],['Complication','Systemic emboli'],['Differential','Culture-negative infection']],[ref('ESC 2023 endocarditis guideline','https://doi.org/10.1093/eurheartj/ehad193')],style='clinical_scenario')

q('Recurrent migratory superficial thrombophlebitis in a patient with weight loss raises concern for which process?', 'Malignancy-associated hypercoagulability, classically associated with adenocarcinoma',[
 ('A specific diagnostic proof of pancreatic cancer without further assessment','The association is not specific enough to establish the primary.'),('A mechanism caused solely by platelet deficiency','Hypercoagulability is not explained by platelet deficiency alone.'),('An indication that venous thrombosis cannot coexist','Superficial and deep thrombotic disease can coexist.')],
 'A vascular pattern can be a clue to systemic disease','**Trousseau-type thrombosis can reflect cancer-associated procoagulant activity.**',['Mucin-producing adenocarcinomas are classic associations.','Other thrombotic and inflammatory causes also occur.'],'**Evaluate the thrombosis and pursue a proportionate malignancy assessment.**',['Treat venous events according to extent and bleeding risk.','Do not infer an exact primary site from the eponym.'],[['Pattern','Migratory thrombophlebitis'],['Mechanism','Hypercoagulability'],['Specificity','Not an exact primary-site test']],[ref('NCI pancreatic cancer professional summary','https://www.cancer.gov/types/pancreatic/hp/pancreatic-treatment-pdq')],style='clinical_scenario')

q('An adult over 40 develops new dermatomyositis with anti-TIF1-gamma antibodies and dysphagia. Which cancer-assessment strategy is most appropriate?', 'Risk-stratified myositis-associated cancer screening in addition to routine age- and sex-appropriate screening',[
 ('No cancer assessment unless a palpable mass is present','The phenotype can signal increased malignancy risk before a mass is evident.'),('Assume every such patient has ovarian cancer','Risk is increased but neither cancer nor one site is guaranteed.'),('Use one normal tumor marker to exclude all associated cancers','No single marker provides that exclusion.')],
 'Myositis subtype and clinical features modify malignancy risk','**Adult dermatomyositis and selected antibodies can identify a higher-risk group.**',['Age, dysphagia and other features inform the recommended strategy.','The IMACS guidance applies within its defined adult-onset time window.'],'**Coordinate a structured screening plan rather than indiscriminate testing.**',['Include routine population screening.','Use additional investigations and follow-up according to the risk category.'],[['Phenotype','Dermatomyositis'],['Risk markers','Age/antibody/clinical features'],['Plan','Risk-stratified screening']],[ref('IMACS international myositis-associated cancer-screening guideline','https://doi.org/10.1038/s41584-023-01045-w')],style='clinical_scenario')

q('A patient with a large mesenchymal tumor has fasting hypoglycemia, suppressed insulin and C-peptide, and low ketones. Which mechanism should be considered?', 'Tumor-derived incompletely processed IGF-II with insulin-like activity',[
 ('Insulinoma as established by suppressed insulin during hypoglycemia','Insulinoma typically causes inappropriate endogenous insulin secretion.'),('Exogenous insulin as proven by low insulin and low C-peptide','Exogenous insulin usually produces detectable high insulin with suppressed C-peptide, subject to assay caveats.'),('Reactive postprandial hypoglycemia as the only explanation','The fasting tumor-associated pattern requires a broader assessment.')],
 'Insulin-like effects can occur without high measured insulin','**Non-islet-cell tumor hypoglycemia can be mediated by big IGF-II.**',['It promotes glucose utilization and suppresses endogenous glucose production.','Critical illness, liver failure, adrenal disease and medicines remain alternatives.'],'**Treat hypoglycemia immediately and investigate its mechanism.**',['Obtain a critical sample when safe without delaying glucose.','Tumor control and selected endocrine measures may be required for recurrence.'],[['Insulin/C-peptide','Suppressed'],['Ketones','Inappropriately low'],['Possible mediator','Big IGF-II']],[ref('Endocrine Society adult hypoglycemia guideline','https://academic.oup.com/jcem/article/94/3/709/2596247')],style='clinical_scenario')

q('A renal mass is accompanied by erythrocytosis with inappropriately elevated erythropoietin. Which explanation is most plausible?', 'Paraneoplastic erythropoietin production or tumor-associated stimulation of the EPO pathway',[
 ('Polycythemia vera established solely by a high hematocrit','PV requires a different assessment and often has suppressed EPO.'),('Relative erythrocytosis proven despite no volume assessment','Plasma-volume contraction is a separate possibility, not established by the stem.'),('Direct replacement of marrow by tumor necessarily increasing all blood counts','Marrow infiltration does not explain the EPO-mediated pattern.')],
 'A renal tumor can cause a distant hematological effect','**RCC is a recognized cause of secondary erythrocytosis.**',['Hypoxia and other EPO-related causes still need consideration.','Not all RCCs produce erythrocytosis.'],'**Evaluate the erythrocytosis and the renal lesion together.**',['Assess symptoms and thrombotic risk.','Do not diagnose a myeloproliferative neoplasm from hematocrit alone.'],[['Secondary erythrocytosis','EPO pathway'],['PV','Different clonal evaluation'],['Renal lesion','Potential paraneoplastic source']],[ref('NCI renal cell cancer professional summary','https://www.cancer.gov/types/kidney/hp/kidney-treatment-pdq')],style='clinical_scenario')

q('A patient with lung cancer has digital clubbing, painful swollen ankles and symmetrical periosteal new bone formation. Which syndrome is most likely?', 'Hypertrophic pulmonary osteoarthropathy',[
 ('Multiple focal lytic skeletal metastases as the best explanation of this entire pattern','Symmetrical periostosis with clubbing favors hypertrophic osteoarthropathy.'),('Isolated rheumatoid arthritis established by ankle pain alone','Clubbing and periostosis require another explanation.'),('Hypercalcemic crisis established by periosteal reaction','The described syndrome is not itself proof of severe hypercalcemia.')],
 'A paraneoplastic skeletal reaction differs from metastatic deposits','**Clubbing, periostosis and arthralgia form a characteristic syndrome.**',['Intrathoracic malignancy is an important association.','Nonmalignant pulmonary and other causes can also occur.'],'**Evaluate the underlying disease and provide symptom control.**',['Distinguish the pattern from focal metastases and inflammatory arthritis.','Treatment of the cause can improve the syndrome.'],[['Digits','Clubbing'],['Bone','Periostosis'],['Joints','Pain/swelling']],[ref('NCI NSCLC professional summary','https://www.cancer.gov/types/lung/hp/non-small-cell-lung-treatment-pdq')],style='clinical_scenario')

q('A patient with squamous-cell carcinoma has hypercalcemia, suppressed intact PTH and elevated PTH-related peptide. Which mechanism best explains the calcium disturbance?', 'Humoral hypercalcemia of malignancy through PTHrP activity',[
 ('Primary hyperparathyroidism as established by suppressed PTH','Primary hyperparathyroidism typically has inappropriately nonsuppressed PTH.'),('Calcitriol-mediated hypercalcemia as proven by high PTHrP','Calcitriol is a different mediator and is assessed separately.'),('An obligatory requirement for extensive visible lytic bone metastases','PTHrP-mediated hypercalcemia can occur without that skeletal burden.')],
 'A circulating mediator can raise calcium without local skeletal metastases','**PTHrP can promote bone resorption and renal calcium retention.**',['Suppressed native PTH supports a non-parathyroid cause.','Malignancy can also raise calcium through osteolysis or calcitriol production.'],'**Treat severity and the underlying cancer while defining the mechanism.**',['Review volume status and renal function.','Use antiresorptive and other treatment according to current guidance.'],[['PTHrP','Humoral mechanism'],['Native PTH','Suppressed'],['Other mechanisms','Osteolysis/calcitriol']],[ref('Endocrine Society malignancy hypercalcemia guideline','https://www.endocrine.org/clinical-practice-guidelines/hypercalcemia')],style='clinical_scenario')

if __name__=='__main__':finalize('Oncology',6,'Cancer Genetics and Paraneoplastic Syndromes','onco-genetics',rows,24)
